"use client";
import * as React from "react";
import { cn } from "../lib/cn";

/* ============================ Browser ============================ */
export interface MockupBrowserProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Adres in de balk. */
  url?: string;
  /** Verbergt de drie knopjes linksboven. */
  hideDots?: boolean;
  /** Donkere chroom, ook in lichte modus. */
  dark?: boolean;
}

/** MockupBrowser — een schermafbeelding in een browservenster zetten. */
export const MockupBrowser = React.forwardRef<HTMLDivElement, MockupBrowserProps>(function MockupBrowser(
  { url, hideDots, dark, className, children, ...rest },
  ref
) {
  return (
    <div ref={ref} className={cn("pxui-mockup", "pxui-mockup-browser", dark && "pxui-mockup-dark", className)} {...rest}>
      <div className="pxui-mockup-bar">
        {!hideDots && <Dots />}
        {url !== undefined && (
          <span className="pxui-mockup-url" title={url}>
            {url}
          </span>
        )}
      </div>
      <div className="pxui-mockup-screen">{children}</div>
    </div>
  );
});

/* ============================ Window ============================ */
export interface MockupWindowProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  title?: React.ReactNode;
  hideDots?: boolean;
  dark?: boolean;
}

/** MockupWindow — venster met titelbalk, voor een desktop-app of dialoog. */
export const MockupWindow = React.forwardRef<HTMLDivElement, MockupWindowProps>(function MockupWindow(
  { title, hideDots, dark, className, children, ...rest },
  ref
) {
  return (
    <div ref={ref} className={cn("pxui-mockup", "pxui-mockup-window", dark && "pxui-mockup-dark", className)} {...rest}>
      <div className="pxui-mockup-bar">
        {!hideDots && <Dots />}
        {title && <span className="pxui-mockup-title">{title}</span>}
      </div>
      <div className="pxui-mockup-screen">{children}</div>
    </div>
  );
});

/* ============================ Phone ============================ */
export interface MockupPhoneProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Breedte van het scherm in px; de hoogte volgt uit de verhouding. */
  width?: number;
  /** Verhouding hoogte/breedte. Standaard 19.5:9, zoals een moderne telefoon. */
  ratio?: number;
  /** "island" is de pil bovenaan, "notch" de bredere inkeping. */
  top?: "island" | "notch" | "none";
  /** Streepje onderaan voor het vegen. */
  homeBar?: boolean;
  dark?: boolean;
}

/** MockupPhone — een schermontwerp in een telefoonframe. */
export const MockupPhone = React.forwardRef<HTMLDivElement, MockupPhoneProps>(function MockupPhone(
  { width = 280, ratio = 19.5 / 9, top = "island", homeBar = true, dark, className, children, style, ...rest },
  ref
) {
  return (
    <div
      ref={ref}
      className={cn("pxui-mockup-phone", dark && "pxui-mockup-dark", className)}
      style={{ width, ...style }}
      {...rest}
    >
      <div className="pxui-mockup-phone-frame" style={{ aspectRatio: `1 / ${ratio}` }}>
        {top !== "none" && <span className={cn("pxui-mockup-phone-top", `pxui-mockup-phone-${top}`)} />}
        <div className="pxui-mockup-screen">{children}</div>
        {homeBar && <span className="pxui-mockup-phone-home" />}
      </div>
    </div>
  );
});

function Dots() {
  return (
    <span className="pxui-mockup-dots" aria-hidden="true">
      <span />
      <span />
      <span />
    </span>
  );
}

/* ============================ Mockups ============================ */
.pxui-mockup {
  --pxui-mockup-chrome: var(--surface-2);
  --pxui-mockup-line: var(--border);
  display: flex; flex-direction: column; overflow: hidden;
  border: 1px solid var(--pxui-mockup-line); border-radius: var(--r-lg);
  background: var(--surface); box-shadow: var(--sh-md);
}
.pxui-mockup-dark {
  --pxui-mockup-chrome: #1b2231;
  --pxui-mockup-line: #2b3446;
  color-scheme: dark;
}

.pxui-mockup-bar {
  display: flex; align-items: center; gap: 12px; flex: none;
  height: 38px; padding: 0 12px;
  background: var(--pxui-mockup-chrome);
  border-bottom: 1px solid var(--pxui-mockup-line);
}

.pxui-mockup-dots { display: inline-flex; gap: 6px; flex: none; }
.pxui-mockup-dots > span {
  width: 10px; height: 10px; border-radius: var(--r-full); background: var(--border-strong);
}
.pxui-mockup-dots > span:nth-child(1) { background: #ec6a5e; }
.pxui-mockup-dots > span:nth-child(2) { background: #f4bf4f; }
.pxui-mockup-dots > span:nth-child(3) { background: #61c554; }

.pxui-mockup-url {
  flex: 1; min-width: 0; height: 24px; padding: 0 12px;
  display: flex; align-items: center;
  background: var(--surface); border: 1px solid var(--pxui-mockup-line);
  border-radius: var(--r-full);
  font-size: 12px; color: var(--text-3);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.pxui-mockup-dark .pxui-mockup-url { background: #131926; }

.pxui-mockup-title {
  flex: 1; text-align: center; font-size: 12.5px; font-weight: 600; color: var(--text-2);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
/* De stippen links even breed compenseren, zodat de titel echt centreert. */
.pxui-mockup-window .pxui-mockup-dots + .pxui-mockup-title { margin-right: 42px; }

.pxui-mockup-screen { flex: 1; min-height: 0; overflow: auto; background: var(--surface); }
.pxui-mockup-dark .pxui-mockup-screen { background: #0f1520; }

/* ---------- Telefoon ---------- */
.pxui-mockup-phone { display: inline-block; }
.pxui-mockup-phone-frame {
  position: relative; width: 100%;
  padding: 11px; border-radius: 40px;
  background: linear-gradient(160deg, #262f3e, #0d1119);
  box-shadow: var(--sh-lg), inset 0 0 0 2px rgba(255, 255, 255, .06);
}
.pxui-mockup-phone-frame > .pxui-mockup-screen {
  width: 100%; height: 100%; border-radius: 30px; overflow: auto;
}

.pxui-mockup-phone-top {
  position: absolute; top: 20px; left: 50%; translate: -50% 0; z-index: 2;
  background: #05070b; border-radius: var(--r-full);
}
.pxui-mockup-phone-island { width: 84px; height: 24px; }
.pxui-mockup-phone-notch { width: 132px; height: 26px; top: 11px; border-radius: 0 0 16px 16px; }

.pxui-mockup-phone-home {
  position: absolute; bottom: 20px; left: 50%; translate: -50% 0; z-index: 2;
  width: 108px; height: 4px; border-radius: var(--r-full);
  background: color-mix(in srgb, var(--text) 35%, transparent);
}

@media (max-width: 480px) {
  .pxui-mockup-phone { max-width: 100%; }
}
